    tldr: "Erasmus MC haematologist and HOVON Vice Chair known for research on the bone marrow microenvironment in MDS.",
    summary: "Marc H.G.P. Raaijmakers is Vice Chair of the HOVON Board and a professor of haematology at Erasmus MC in Rotterdam. His laboratory studies how the bone marrow microenvironment contributes to myelodysplastic syndromes and leukaemia. He combines clinical haematology with translational research and cooperative-group leadership.",
    profiles: [{ label: "Society page", url: "https://hovon.nl/en/about-hovon" }, { label: "PubMed", url: "https://pubmed.ncbi.nlm.nih.gov/?term=Raaijmakers+MHGP%5BAuthor%5D" }],
